BEGIN TRANSACTION;
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "cb_attachments" ("id" char(32) NOT NULL PRIMARY KEY, "original_name" varchar(255) NOT NULL, "storage_path" varchar(500) NOT NULL, "mime_type" varchar(100) NOT NULL, "size" bigint NOT NULL, "owner_id" varchar(100) NOT NULL, "is_public" bool NOT NULL, "created_at" datetime NOT NULL, "storage_config_id" varchar(100) NULL);
CREATE TABLE "cb_bbtalk_tag_relations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "bbtalk_id" integer NOT NULL, "tag_id" integer NOT NULL);
CREATE TABLE "cb_bbtalks" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "create_time" datetime NOT NULL, "update_time" datetime NOT NULL, "uid" varchar(22) NOT NULL UNIQUE, "content" text NOT NULL, "visibility" varchar(16) NOT NULL, "attachments" text NOT NULL CHECK ((JSON_VALID("attachments") OR "attachments" IS NULL)), "context" text NOT NULL CHECK ((JSON_VALID("context") OR "context" IS NULL)), "user_id" bigint NOT NULL, "is_pinned" bool NOT NULL);
CREATE TABLE "cb_comments" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "create_time" datetime NOT NULL, "update_time" datetime NOT NULL, "uid" varchar(22) NOT NULL UNIQUE, "content" text NOT NULL, "bbtalk_id" integer NOT NULL, "user_id" bigint NOT NULL);
CREATE TABLE "cb_desktop_authorizations" ("code_hash" varchar(64) NOT NULL PRIMARY KEY, "challenge" varchar(43) NOT NULL, "redirect_uri" varchar(200) NOT NULL, "expires_at" datetime NOT NULL, "consumed" bool NOT NULL, "user_id" bigint NOT NULL REFERENCES "cb_users" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "cb_identities" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "identity_type" varchar(32) NOT NULL, "identifier" varchar(255) NOT NULL, "credential" varchar(255) NOT NULL, "provider" varchar(32) NOT NULL, "provider_user_id" varchar(255) NOT NULL, "is_verified" bool NOT NULL, "is_primary" bool NOT NULL, "create_time" datetime NOT NULL, "update_time" datetime NOT NULL, "last_used" datetime NULL, "user_id" bigint NOT NULL);
CREATE TABLE "cb_password_recovery" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code_hash" varchar(64) NOT NULL, "email" varchar(254) NOT NULL, "credential_version" integer unsigned NOT NULL CHECK ("credential_version" >= 0), "expires_at" datetime NOT NULL, "user_id" bigint NOT NULL UNIQUE REFERENCES "cb_users" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "cb_submission_receipts" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "key" varchar(128) NOT NULL, "payload_hash" varchar(64) NOT NULL, "created_at" datetime NOT NULL, "record_id" integer NULL REFERENCES "cb_bbtalks" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "cb_users" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "submission_user_key_unique" UNIQUE ("user_id", "key"));
CREATE TABLE "cb_tags" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "create_time" datetime NOT NULL, "update_time" datetime NOT NULL, "uid" varchar(22) NOT NULL UNIQUE, "name" varchar(50) NOT NULL, "color" varchar(7) NOT NULL, "sort_order" real NOT NULL, "user_id" bigint NOT NULL);
CREATE TABLE "cb_user_storage_settings" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "storage_type" varchar(16) NOT NULL, "s3_access_key_id" varchar(255) NOT NULL, "s3_secret_access_key" varchar(255) NOT NULL, "s3_bucket_name" varchar(255) NOT NULL, "s3_region_name" varchar(64) NOT NULL, "s3_endpoint_url" varchar(500) NOT NULL, "s3_custom_domain" varchar(255) NOT NULL, "is_active" bool NOT NULL, "create_time" datetime NOT NULL, "update_time" datetime NOT NULL, "name" varchar(100) NOT NULL, "user_id" bigint NOT NULL);
CREATE TABLE "cb_users" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "username" varchar(150) NOT NULL UNIQUE, "email" varchar(254) NOT NULL, "display_name" varchar(150) NOT NULL, "avatar" varchar(200) NOT NULL, "bio" text NOT NULL, "is_active" bool NOT NULL, "is_staff" bool NOT NULL, "is_superuser" bool NOT NULL, "create_time" datetime NOT NULL, "update_time" datetime NOT NULL, "last_login" datetime NULL, "credential_version" integer unsigned NOT NULL CHECK ("credential_version" >= 0));
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "cb_users" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "token_blacklist_blacklistedtoken" ("blacklisted_at" datetime NOT NULL, "token_id" bigint NOT NULL UNIQUE REFERENCES "token_blacklist_outstandingtoken" ("id") DEFERRABLE INITIALLY DEFERRED, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT);
CREATE TABLE "token_blacklist_outstandingtoken" ("token" text NOT NULL, "created_at" datetime NULL, "expires_at" datetime NOT NULL, "user_id" bigint NULL REFERENCES "cb_users" ("id") DEFERRABLE INITIALLY DEFERRED, "jti" varchar(255) NOT NULL UNIQUE, "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT);
CREATE INDEX "tag_user_time_idx" ON "cb_tags" ("user_id", "update_time" DESC);
CREATE INDEX "tag_user_name_idx" ON "cb_tags" ("user_id", "name");
